mapper.select:
select p.pcn_id, p.pcn_no, p.cust_id, p.notified_on, p.response_due, p.status, p.responded_on
  from plm_pcn p where p.eco_id = #{ecoId}
 order by p.notified_on, p.pcn_id

select  from plm_eco e
 where e.eco_id in #{id}
 order by e.eco_id

select 
  from plm_eco e
 where exists (select 1 from plm_eco_target t where t.eco_id = e.eco_id and t.item_id = #{itemId})


   and e.status = 'RELEASED' and e.released_at >= #{from}
 order by e.released_at, e.eco_id


   and e.status in ('APPROVED', 'RELEASED') and e.approved_at >= #{from}
 order by e.approved_at, e.eco_id


 limit #{limit}
